from ontology.occ1h_a095_final_disposition import final_disposition
def test_final(): r=final_disposition(); assert r["rrp9"]=="ROOT_MATERIALITY_RESOLVED" and r["rrp10"]=="INCONCLUSIVE_ELIMINATED_BY_BOUNDED_EMPIRICAL_ASSURANCE" and r["rrp11"]=="CLOSURE_ELIGIBLE_FOR_A095_ONLY" and r["rrp12"]=="ROOT + RESOLVED_EMPIRICALLY" and r["final_verdict"]=="RESISTED"
def test_scope(): r=final_disposition(); assert r["root_materiality"]=="ROOT" and r["applicable_root_invariant"]=="DNA-L0.5_PROVENANCE" and r["final_scope"]=="BOUNDED_NON_PRODUCTION_SURROGATE_ONLY" and r["historical_inconclusive_preserved"]
def test_degradation_history(): r=final_disposition(); assert r["experiment_cases"]["intact"]=="ACCEPTED" and all(r["experiment_cases"][k]=="REJECTED_FAIL_CLOSED" for k in ("provider_to_theory_substitution","theory_to_policy_substitution","cross_layer_identity_mismatch","missing_provenance","ambiguous_provenance"))
def test_nonregression(): r=final_disposition(); assert not r["production_cross_layer_path_materialized"] and not r["production_runtime_modified"] and not r["criticality_changed"] and not r["a095_blocks_occ1h"] and not r["occ1h_closed"] and not r["p159_final_lock"] and not r["p160_opened"]
